import AVFoundation
import Foundation

/**
 * Interaction tones for iPadOS — the counterpart of
 * `android/app/src/main/java/com/happypix/booth/SimpleSoundModule.kt`.
 *
 * The six WAV files in `ios/booth/Sounds` are generated by
 * `scripts/generate_tones.py` from the Electron kiosk's WebAudio definitions, so
 * all three clients share one sound design. Players are cached per cue because
 * a booth fires `click` on every tap and allocating a player per tap would
 * stutter.
 */
@objc(SimpleSound)
class SimpleSoundModule: NSObject {

  private static let cues = ["click", "select", "countdown", "shutter", "success", "beep"]
  private var players: [String: AVAudioPlayer] = [:]
  private let lock = NSLock()

  override init() {
    super.init()
    configureSession()
    // Warm the cache so the very first tap is not silent while the file loads.
    SimpleSoundModule.cues.forEach { _ = player(for: $0) }
  }

  private func configureSession() {
    let session = AVAudioSession.sharedInstance()
    // .playback keeps the cues audible even when the side switch is on silent —
    // a kiosk must be heard, and the guest cannot change this. mixWithOthers so
    // an event's background music is not stopped by a shutter click.
    try? session.setCategory(.playback, mode: .default, options: [.mixWithOthers])
    try? session.setActive(true)
  }

  private func player(for name: String) -> AVAudioPlayer? {
    lock.lock()
    defer { lock.unlock() }
    if let cached = players[name] { return cached }
    guard let url = Bundle.main.url(forResource: name, withExtension: "wav", subdirectory: "Sounds")
              ?? Bundle.main.url(forResource: name, withExtension: "wav") else {
      return nil
    }
    guard let player = try? AVAudioPlayer(contentsOf: url) else { return nil }
    player.prepareToPlay()
    players[name] = player
    return player
  }

  @objc func play(_ name: String) {
    guard let player = player(for: name) else { return }
    lock.lock()
    player.currentTime = 0   // replay from the top on rapid taps
    player.play()
    lock.unlock()
  }

  @objc func stopAll() {
    lock.lock()
    players.values.forEach { $0.stop() }
    lock.unlock()
  }

  @objc static func requiresMainQueueSetup() -> Bool { true }
}
